            f"保單條款第十三條及附表二，第 {article_pages['total_disability']} 頁起；{table_ref}",
            limit_scope="per_policy",
            conditions=["給付後本契約終止", f"完全{disability_term}後身故不另給付第十二條身故保險金"],
