            taiwan_return_article_ref(disability_article, "完全失能保險金的給付"),
            calculation_basis="greater_of",
            amount_role="payout",
            limit_scope="per_event",
            aggregation_rule="highest",
            rate_percent=100,
            unit_key="annual_insured_amount",
